import re


def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    def parse_version(text):
        if not isinstance(text, str):
            raise ValueError("invalid version")

        m = re.fullmatch(
            r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
            r"(?:-(.+))?",
            text,
        )
        if not m:
            raise ValueError("invalid version")

        major, minor, patch, prerelease_text = m.groups()
        major = int(major)
        minor = int(minor)
        patch = int(patch)

        if prerelease_text is None:
            prerelease = None
        else:
            identifiers = prerelease_text.split(".")
            if not identifiers:
                raise ValueError("invalid version")

            parsed = []
            for ident in identifiers:
                if not ident:
                    raise ValueError("invalid version")
                if not re.fullmatch(r"[0-9A-Za-z-]+", ident):
                    raise ValueError("invalid version")
                if re.fullmatch(r"[0-9]+", ident):
                    if len(ident) > 1 and ident[0] == "0":
                        raise ValueError("invalid version")
                    parsed.append(int(ident))
                else:
                    parsed.append(ident)
            prerelease = tuple(parsed)

        return (major, minor, patch, prerelease)

    def compare_versions(a, b):
        amaj, amin, apat, apre = a
        bmaj, bmin, bpat, bpre = b

        if (amaj, amin, apat) != (bmaj, bmin, bpat):
            return -1 if (amaj, amin, apat) < (bmaj, bmin, bpat) else 1

        if apre is None and bpre is None:
            return 0
        if apre is None:
            return 1
        if bpre is None:
            return -1

        for x, y in zip(apre, bpre):
            x_num = isinstance(x, int)
            y_num = isinstance(y, int)

            if x_num and y_num:
                if x != y:
                    return -1 if x < y else 1
            elif x_num:
                return -1
            elif y_num:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1

        if len(apre) != len(bpre):
            return -1 if len(apre) < len(bpre) else 1

        return 0

    def parse_comparator(text):
        if not isinstance(text, str) or not text:
            raise ValueError("invalid comparator")

        op = ""
        rest = text

        if text.startswith(">="):
            op = ">="
            rest = text[2:]
        elif text.startswith("<="):
            op = "<="
            rest = text[2:]
        elif text.startswith(">"):
            op = ">"
            rest = text[1:]
        elif text.startswith("<"):
            op = "<"
            rest = text[1:]
        elif text.startswith("^"):
            op = "^"
            rest = text[1:]
        elif text.startswith("~"):
            op = "~"
            rest = text[1:]
        elif text.startswith("="):
            op = "="
            rest = text[1:]

        if not rest:
            raise ValueError("invalid comparator")

        named = parse_version(rest)
        return op, named

    def comparator_satisfied(version, op, named):
        cmp = compare_versions(version, named)

        if op == "" or op == "=":
            return cmp == 0
        if op == ">":
            return cmp > 0
        if op == ">=":
            return cmp >= 0
        if op == "<":
            return cmp < 0
        if op == "<=":
            return cmp <= 0

        if op == "^":
            maj, min, pat, _ = named
            if maj > 0:
                upper = (maj + 1, 0, 0, None)
            elif min > 0:
                upper = (0, min + 1, 0, None)
            else:
                upper = (0, 0, pat + 1, None)
            return compare_versions(version, named) >= 0 and compare_versions(version, upper) < 0

        if op == "~":
            maj, min, pat, _ = named
            upper = (maj, min + 1, 0, None)
            return compare_versions(version, named) >= 0 and compare_versions(version, upper) < 0

        raise ValueError("invalid comparator")

    def prerelease_rule_satisfied(version, comparators):
        if version[3] is None:
            return True

        for _, named in comparators:
            if (
                version[:3] == named[:3]
                and named[3] is not None
            ):
                return True

        return False

    if not isinstance(version, str):
        raise ValueError("invalid version")

    parsed_version = parse_version(version)

    if not isinstance(rng, str):
        raise ValueError("invalid range")

    raw_sets = rng.split("||")
    parsed_sets = []

    for raw_set in raw_sets:
        comparators_text = raw_set.split()
        if not comparators_text:
            raise ValueError("invalid range")

        comparators = []
        for comparator_text in comparators_text:
            comparators.append(parse_comparator(comparator_text))

        parsed_sets.append(comparators)

    for comparators in parsed_sets:
        if not prerelease_rule_satisfied(parsed_version, comparators):
            continue

        if all(
            comparator_satisfied(parsed_version, op, named)
            for op, named in comparators
        ):
            return True

    return False
