from datetime import datetime, timedelta


def next_fire(expr, after):
    """Return the first naive datetime STRICTLY after `after` (a naive datetime) that matches cron expression `expr`.
    Results always have second == 0 and microsecond == 0.

    `expr` has exactly 5 whitespace-separated fields: minute (0-59), hour (0-23), day-of-month (1-31),
    month (1-12), day-of-week (0-7, where both 0 and 7 mean Sunday, 1 = Monday ... 6 = Saturday).
    Each field is a comma-separated list of items. An item is "*" (the whole field range), "N", or "A-B" (A <= B),
    optionally followed by "/S" (S >= 1): take every S-th value of the item starting at its first value.
    "*/S" starts at the field minimum and "N/S" means N through the field maximum in steps of S.

    Day matching: a field is "unrestricted" only if it is exactly "*". If both day-of-month and day-of-week are
    restricted, a day matches when EITHER matches; otherwise both must match.

    Empty items, out-of-range values, A > B, S < 1, non-digit characters, or a wrong number of fields raise
    ValueError. If the expression has no match within 3000 days after `after` (e.g. "0 0 30 2 *"), raise ValueError.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError

    ranges = [
        (0, 59),
        (0, 23),
        (1, 31),
        (1, 12),
        (0, 7),
    ]

    def parse_field(field, lo, hi):
        if field == "":
            raise ValueError

        values = set()
        items = field.split(",")

        for item in items:
            if item == "":
                raise ValueError

            if "/" in item:
                base, step_s = item.split("/", 1)
                if "/" in step_s:
                    raise ValueError
                if not step_s.isdigit():
                    raise ValueError
                step = int(step_s)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                a_s, b_s = base.split("-", 1)
                if "-" in b_s:
                    raise ValueError
                if not a_s.isdigit() or not b_s.isdigit():
                    raise ValueError
                start = int(a_s)
                end = int(b_s)
                if start > end:
                    raise ValueError
            else:
                if not base.isdigit():
                    raise ValueError
                start = int(base)
                end = hi

            if start < lo or end > hi:
                raise ValueError

            for v in range(start, end + 1, step):
                values.add(v)

        return values

    minute_values = parse_field(fields[0], *ranges[0])
    hour_values = parse_field(fields[1], *ranges[1])
    dom_values = parse_field(fields[2], *ranges[2])
    month_values = parse_field(fields[3], *ranges[3])
    dow_values = parse_field(fields[4], *ranges[4])

    dow_values = {0 if v == 7 else v for v in dow_values}

    dom_unrestricted = fields[2] == "*"
    dow_unrestricted = fields[4] == "*"

    minutes = sorted(minute_values)
    hours = sorted(hour_values)
    months = sorted(month_values)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)

    for day_offset in range(3001):
        day = start + timedelta(days=day_offset)

        if day.month not in month_values:
            continue

        dom_ok = day.day in dom_values
        dow_ok = ((day.weekday() + 1) % 7) in dow_values

        if dom_unrestricted and dow_unrestricted:
            day_ok = True
        elif dom_unrestricted:
            day_ok = dow_ok
        elif dow_unrestricted:
            day_ok = dom_ok
        else:
            day_ok = dom_ok or dow_ok

