import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    try:
        result = copy.deepcopy(doc)

        if not isinstance(ops, list):
            raise PatchError

        for op in ops:
            if not isinstance(op, dict):
                raise PatchError

            kind = op.get("op")
            if kind not in {"add", "remove", "replace", "move", "copy", "test"}:
                raise PatchError

            if "path" not in op:
                raise PatchError

            path = op["path"]
            if not isinstance(path, str):
                raise PatchError

            if kind in {"add", "replace", "test"} and "value" not in op:
                raise PatchError

            if kind in {"move", "copy"} and "from" not in op:
                raise PatchError

            if kind == "add":
                result = _add(result, path, copy.deepcopy(op["value"]))
            elif kind == "remove":
                result = _remove(result, path)
            elif kind == "replace":
                result = _replace(result, path, copy.deepcopy(op["value"]))
            elif kind == "move":
                src = op["from"]
                if not isinstance(src, str):
                    raise PatchError
                if _path_is_strict_descendant(path, src):
                    raise PatchError
                if src == path:
                    _get(result, src)
                else:
                    moved = _remove(result, src)
                    result = _add(result, path, moved)
            elif kind == "copy":
                src = op["from"]
                if not isinstance(src, str):
                    raise PatchError
                copied = copy.deepcopy(_get(result, src))
                result = _add(result, path, copied)
            elif kind == "test":
                if not _json_equal(_get(result, path), op["value"]):
                    raise PatchError

        return result
    except PatchError:
        raise


def _parse_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise PatchError

    tokens = []
    for raw_token in pointer[1:].split("/"):
        token = []
        i = 0
        while i < len(raw_token):
            ch = raw_token[i]
            if ch == "~":
                if i + 1 >= len(raw_token):
                    raise PatchError
                nxt = raw_token[i + 1]
                if nxt == "0":
                    token.append("~")
                elif nxt == "1":
                    token.append("/")
                else:
                    raise PatchError
                i += 2
            else:
                token.append(ch)
                i += 1
        tokens.append("".join(token))
    return tokens


def _is_index(token):
    if token == "-":
        return True
    if not token or not token.isdigit():
        return False
    if len(token) > 1 and token[0] == "0":
        return False
    return True


def _path_is_strict_descendant(path, ancestor):
    p = _parse_pointer(path)
    a = _parse_pointer(ancestor)
    return len(p) > len(a) and p[:len(a)] == a


def _get(doc, pointer):
    tokens = _parse_pointer(pointer)
    cur = doc
    for token in tokens:
        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            if not _is_index(token):
                raise PatchError
            if token == "-":
                raise PatchError
            idx = int(token)
            if idx < 0 or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError
    return cur


def _remove(doc, pointer):
    if pointer == "":
        raise PatchError

    tokens = _parse_pointer(pointer)
    cur = doc
    for token in tokens[:-1]:
        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            if not _is_index(token) or token == "-":
                raise PatchError
            idx = int(token)
            if idx < 0 or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError

    token = tokens[-1]
    if isinstance(cur, dict):
        if token not in cur:
            raise PatchError
        value = cur.pop(token)
    elif isinstance(cur, list):
        if not _is_index(token) or token == "-":
            raise PatchError
        idx = int(token)
        if idx < 0 or idx >= len(cur):
            raise PatchError
        value = cur.pop(idx)
    else:
        raise PatchError

    return value


def _replace(doc, pointer, value):
    if pointer == "":
        return value

    tokens = _parse_pointer(pointer)
    cur = doc
    for token in tokens[:-1]:
        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            if not _is_index(token) or token == "-":
                raise PatchError
            idx = int(token)
            if idx < 0 or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError

    token = tokens[-1]
    if isinstance(cur, dict):
        if token not in cur:
            raise PatchError
        cur[token] = value
    elif isinstance(cur, list):
        if not _is_index(token) or token == "-":
            raise PatchError
        idx = int(token)
        if idx < 0 or idx >= len(cur):
            raise PatchError
        cur[idx] = value
    else:
        raise PatchError

    return doc


def _add(doc, pointer, value):
    if pointer == "":
        return value

    tokens = _parse_pointer(pointer)
    cur = doc
    for token in tokens[:-1]:
        if isinstance(cur, dict):
            if token not in cur:
                raise PatchError
            cur = cur[token]
        elif isinstance(cur, list):
            if not _is_index(token) or token == "-":
                raise PatchError
            idx = int(token)
            if idx < 0 or idx >= len(cur):
                raise PatchError
            cur = cur[idx]
        else:
            raise PatchError

    token = tokens[-1]
    if isinstance(cur, dict):
        cur[token] = value
    elif isinstance(cur, list):
        if not _is_index(token):
            raise PatchError
        if token == "-":
            cur.append(value)
        else:
            idx = int(token)
            if idx < 0 or idx > len(cur):
                raise PatchError
            cur.insert(idx, value)
    else:
        raise PatchError

    return doc


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(_json_equal(a[k], b[k]) for k in a)

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(_json_equal(x, y) for x, y in zip(a, b))

    return a == b
