            elif c == "*":
                tokens.append(("star", None))
                i += 1
            elif c == "[":
                j = i + 1
                if j < n and seg[j] == "!":
                    j += 1
                if j < n and seg[j] == "]":
                    j += 1
                while j < n and seg[j] != "]":
                    j += 1
                if j >= n:
                    raise ValueError("unterminated [")

                body = seg[i + 1 : j]
                negate = False
                if body.startswith("!"):
