                ranges = []
                k = 0
                m = len(body)
                while k < m:
                    if (
                        k + 2 < m
                        and body[k] != "-"
                        and body[k + 1] == "-"
                        and body[k + 2] != "]"
                    ):
                        lo = body[k]
                        hi = body[k + 2]
                        if lo <= hi:
