        n = len(psegs)
        m = len(pstrs)
        dp = [[False] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = True

        for i in range(1, n + 1):
            if psegs[i - 1] == "**":
                dp[i][0] = dp[i - 1][0]

        for i in range(1, n + 1):
