                for j in range(1, m + 1):
                    dp[i][j] = dp[i - 1][j - 1] and match_segment(toks, pstrs[j - 1])

        return dp[n][m]

    psegs = split_pattern(pattern)
    pstrs = path.split("/")
    return match_segments(psegs, pstrs)
