    pre = m.group(4)

    if pre is None:
        return (major, minor, patch, None)

    identifiers = pre.split(".")
    parsed = []
    for ident in identifiers:
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"invalid version: {s!r}")
            parsed.append((True, int(ident)))
        else:
            parsed.append((False, ident))

    return (major, minor, patch, tuple(parsed))


def compare_versions(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    a_pre, b_pre = a[3], b[3]

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        x_num, x_val = x
        y_num, y_val = y

        if x_num and y_num:
            if x_val != y_val:
                return -1 if x_val < y_val else 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            if x_val != y_val:
                return -1 if x_val < y_val else 1

    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1

    return 0


def make_comparator(op, version):
    major, minor, patch, _ = version

    if op == "^":
        if major > 0:
            upper = (major + 1, 0, 0, None)
        elif minor > 0:
            upper = (0, minor + 1, 0, None)
        else:
            upper = (0, 0, patch + 1, None)
        return ("^", version, upper)

    if op == "~":
        upper = (major, minor + 1, 0, None)
        return ("~", version, upper)

    return (op, version, None)


def parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError("invalid range")

    raw_sets = rng.split("||")
    parsed_sets = []

    for raw_set in raw_sets:
        set_text = raw_set.strip()
        if not set_text:
            raise ValueError("invalid range")

        comparators = []
        for comp in set_text.split():
            if comp.startswith(">="):
                op, rest = ">=", comp[2:]
            elif comp.startswith("<="):
                op, rest = "<=", comp[2:]
            elif comp.startswith(">"):
                op, rest = ">", comp[1:]
            elif comp.startswith("<"):
                op, rest = "<", comp[1:]
            elif comp.startswith("="):
                op, rest = "=", comp[1:]
            elif comp.startswith("^"):
                op, rest = "^", comp[1:]
            elif comp.startswith("~"):
                op, rest = "~", comp[1:]
            else:
                op, rest = "=", comp

            if not rest:
                raise ValueError("invalid range")

            version = parse_version(rest)
            comparators.append(make_comparator(op, version))

        parsed_sets.append(comparators)

    return parsed_sets


def satisfies_set(version, comparators):
    has_prerelease = version[3] is not None

    if has_prerelease:
        prerelease_match = False
        for _, named_version, _ in comparators:
            if (
                named_version[3] is not None
                and named_version[:3] == version[:3]
            ):
                prerelease_match = True
                break

        if not prerelease_match:
            return False

    for op, named_version, upper in comparators:
        if op == "=":
            if compare_versions(version, named_version) != 0:
                return False
        elif op == ">":
            if compare_versions(version, named_version) <= 0:
                return False
        elif op == ">=":
            if compare_versions(version, named_version) < 0:
                return False
        elif op == "<":
            if compare_versions(version, named_version) >= 0:
                return False
        elif op == "<=":
            if compare_versions(version, named_version) > 0:
                return False
        elif op in ("^", "~"):
            if compare_versions(version, named_version) < 0:
                return False
            if compare_versions(version, upper) >= 0:
                return False
        else:
            raise ValueError("invalid comparator")

    return True


def satisfies(version, rng):
    parsed_version = parse_version(version)
    parsed_range = parse_range(rng)

    return any(satisfies_set(parsed_version, comparators) for comparators in parsed_range)
