        if field == "":
            raise ValueError

        unrestricted = field == "*"
        values = set()

        for item in field.split(","):
            if item == "":
                raise ValueError

            if "/" in item:
                base, step_s = item.split("/", 1)
                step = parse_int(step_s)
                if step < 1:
                    raise ValueError
            else:
                base = item
                step = 1

            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                a_s, b_s = base.split("-", 1)
                a = parse_int(a_s)
                b = parse_int(b_s)
                if a < lo or b > hi or a > b:
                    raise ValueError
                start, end = a, b
            else:
                n = parse_int(base)
                if n < lo or n > hi:
                    raise ValueError
                start, end = n, hi

            values.update(range(start, end + 1, step))

        return values, unrestricted

    minutes, _ = parse_field(fields[0], 0, 59)
    hours, _ = parse_field(fields[1], 0, 23)
    doms, dom_unrestricted = parse_field(fields[2], 1, 31)
    months, _ = parse_field(fields[3], 1, 12)
    dows, dow_unrestricted = parse_field(fields[4], 0, 7)

