def glob_match(pattern, path):
    r"""Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def parse_pattern(p):
        segments = []
        current = []
        i = 0
        n = len(p)

        while i < n:
            c = p[i]

            if c == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing lone backslash")
                current.append(("literal", p[i + 1]))
                i += 2
                continue

            if c == "/":
                segments.append(current)
                current = []
                i += 1
                continue

            if c == "?":
                current.append(("any", None))
                i += 1
                continue

            if c == "*":
                current.append(("star", None))
                i += 1
                continue

            if c == "[":
                i += 1
                negated = False
                if i < n and p[i] == "!":
                    negated = True
                    i += 1

                members = []
                if i < n and p[i] == "]":
                    members.append(("char", "]"))
                    i += 1

                terminated = False
                while i < n:
                    c = p[i]
                    if c == "]":
                        terminated = True
                        i += 1
                        break

                    if c == "-" and members and i + 1 < n and p[i + 1] != "]":
                        prev = members[-1]
                        if prev[0] == "char":
                            start = prev[1]
                            end = p[i + 1]
                            if start <= end:
                                members[-1] = ("range", start, end)
                            else:
                                members[-1] = ("char", start)
                                members.append(("char", "-"))
                                members.append(("char", end))
                            i += 2
                            continue

                    if c == "-" and not members:
                        members.append(("char", "-"))
                        i += 1
                        continue

                    if c == "-" and members and i + 1 >= n:
                        members.append(("char", "-"))
                        i += 1
                        continue

                    if c == "-" and members and i + 1 < n and p[i + 1] == "]":
                        members.append(("char", "-"))
                        i += 1
                        continue

                    members.append(("char", c))
                    i += 1

                if not terminated:
                    raise ValueError("unterminated [")

                current.append(("set", negated, members))
                continue

            current.append(("literal", c))
            i += 1

        segments.append(current)
        return segments

    def parse_path(p):
        if p == "":
            return []
        return p.split("/")

    def match_segment(tokens, text):
        def match_from(ti, si):
            if ti == len(tokens):
                return si == len(text)

            kind = tokens[ti][0]

            if kind == "literal":
                ch = tokens[ti][1]
                return si < len(text) and text[si] == ch and match_from(ti + 1, si + 1)

            if kind == "any":
                return si < len(text) and text[si] != "/" and match_from(ti + 1, si + 1)

            if kind == "star":
                for k in range(si, len(text) + 1):
                    if match_from(ti + 1, k):
                        return True
                return False

            if kind == "set":
                _, negated, members = tokens[ti]
                if si >= len(text) or text[si] == "/":
                    return False
                ch = text[si]
                in_set = False
                for member in members:
                    if member[0] == "char":
                        if ch == member[1]:
                            in_set = True
                            break
                    else:
                        _, start, end = member
                        if start <= ch <= end:
                            in_set = True
                            break
                if in_set != negated:
                    return False
                return match_from(ti + 1, si + 1)

            return False

        return match_from(0, 0)

    def match_segments(pattern_segments, path_segments):
        def match_from(pi, si):
            if pi == len(pattern_segments):
                return si == len(path_segments)

            seg = pattern_segments[pi]

            if len(seg) == 2 and seg[0][0] == "star" and seg[1][0] == "star":
                for k in range(si, len(path_segments) + 1):
                    if match_from(pi + 1, k):
                        return True
                return False

            if si >= len(path_segments):
                return False

            if not match_segment(seg, path_segments[si]):
                return False

            return match_from(pi + 1, si + 1)

        return match_from(0, 0)

    return match_segments(parse_pattern(pattern), parse_path(path))
