from collections import namedtuple
from decimal import Decimal
import re

Event = namedtuple("Event", "id kind account target amount")

_AMOUNT_RE = re.compile(r"\A\d+(?:\.\d{1,2})?\Z")


def parse_event(raw):
    """Validate a raw event dict and return an Event.

    Required keys: "id" (non-empty str), "kind" ("deposit", "withdraw" or "transfer"), "account" (non-empty str) and
    "amount" (a str of digits, optionally followed by "." and one or two digits, e.g. "5", "0.1", "12.34"; its value
    must be > 0). A transfer also needs "target" (non-empty str, different from "account"); other kinds ignore it.
    Anything else (missing keys, wrong types, "1e2", "1.234", "-5", "0.00", ...) raises ValueError.
    """
    try:
        event_id = raw["id"]
        kind = raw["kind"]
        account = raw["account"]
        amount_raw = raw["amount"]
    except KeyError as exc:
        raise ValueError(f"missing required key: {exc}") from exc

    if not isinstance(event_id, str) or not event_id:
        raise ValueError("id must be a non-empty string")

    if not isinstance(kind, str) or kind not in ("deposit", "withdraw", "transfer"):
        raise ValueError("bad kind")

    if not isinstance(account, str) or not account:
        raise ValueError("account must be a non-empty string")

    if not isinstance(amount_raw, str) or not _AMOUNT_RE.match(amount_raw):
        raise ValueError("amount must be a positive decimal string with at most two fractional digits")

    amount = Decimal(amount_raw)
    if amount <= 0:
        raise ValueError("amount must be positive")

    target = None
    if kind == "transfer":
        try:
            target = raw["target"]
        except KeyError as exc:
            raise ValueError(f"missing required key: {exc}") from exc

        if not isinstance(target, str) or not target:
            raise ValueError("transfer target must be a non-empty string")
        if target == account:
            raise ValueError("transfer target must differ from account")

    return Event(event_id, kind, account, target, amount)
