def satisfies(version, rng):
    """Return True if `version` satisfies the range `rng`, else False.

    Versions are "MAJOR.MINOR.PATCH" optionally followed by "-PRERELEASE", where PRERELEASE is one or more
    dot-separated identifiers made of [0-9A-Za-z-]. MAJOR, MINOR, PATCH and purely numeric prerelease identifiers
    are non-negative integers without leading zeros ("0" is fine). Build metadata ("+...") is not allowed.
    An invalid version or range raises ValueError; the WHOLE range is validated even if an earlier part matches.

    Precedence (SemVer 2.0.0): compare MAJOR, MINOR, PATCH numerically. A version with a prerelease is lower than
    the same version without one. Prerelease identifiers are compared left to right: numeric ones numerically,
    alphanumeric ones in ASCII order, numeric always lower than alphanumeric, and if all shared identifiers are
    equal the version with fewer identifiers is lower.

    Range grammar: one or more comparator sets separated by "||" (whitespace around "||" is ignored). The range
    is satisfied if ANY set is satisfied. A set is one or more comparators separated by whitespace; it is
    satisfied if ALL its comparators are. An empty set (e.g. "1.0.0 ||") is invalid. Comparators, with no
    whitespace between operator and version:
        "V" or "=V"   equal to V
        ">V" ">=V" "<V" "<=V"
        "^V"          >=V and below the next "significant" version: < (MAJOR+1).0.0 if MAJOR > 0,
                      else < 0.(MINOR+1).0 if MINOR > 0, else < 0.0.(PATCH+1)
        "~V"          >=V and < MAJOR.(MINOR+1).0

    Prerelease rule: a version that HAS a prerelease satisfies a set only if, in addition, some comparator in that
    set names a version with the same MAJOR.MINOR.PATCH that also has a prerelease (for ^V and ~V the named
    version is V). Versions without a prerelease are not affected by this rule.
    """
    def parse_version(s):
        if not isinstance(s, str) or not s:
            raise ValueError("invalid version")

        if "+" in s:
            raise ValueError("invalid version")

        if "-" in s:
            base, prerelease = s.split("-", 1)
        else:
            base, prerelease = s, None

        parts = base.split(".")
        if len(parts) != 3:
            raise ValueError("invalid version")

        def parse_number(part):
            if not part:
                raise ValueError("invalid version")
            if not part.isdigit():
                raise ValueError("invalid version")
            if len(part) > 1 and part[0] == "0":
                raise ValueError("invalid version")
            return int(part)

        major, minor, patch = (parse_number(p) for p in parts)

        pre = None
        if prerelease is not None:
            if not prerelease:
                raise ValueError("invalid version")
            identifiers = prerelease.split(".")
            if not identifiers:
                raise ValueError("invalid version")
            for ident in identifiers:
                if not ident:
                    raise ValueError("invalid version")
                if not all(c.isalnum() or c == "-" for c in ident):
                    raise ValueError("invalid version")
                if ident.isdigit():
                    if len(ident) > 1 and ident[0] == "0":
                        raise ValueError("invalid version")
            pre = tuple(identifiers)

        return (major, minor, patch, pre)

    def compare_versions(a, b):
        for i in range(3):
            if a[i] != b[i]:
                return -1 if a[i] < b[i] else 1

        a_pre = a[3]
        b_pre = b[3]

        if a_pre is None and b_pre is None:
            return 0
        if a_pre is None:
            return 1
        if b_pre is None:
            return -1

        for x, y in zip(a_pre, b_pre):
            x_num = x.isdigit()
            y_num = y.isdigit()

            if x_num and y_num:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif x_num:
                return -1
            elif y_num:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1

        if len(a_pre) != len(b_pre):
            return -1 if len(a_pre) < len(b_pre) else 1

        return 0

    def parse_comparator(token):
        if not token:
            raise ValueError("invalid comparator")

        if token[0] in ">=<^~=":
            if token[0] == ">":
                if len(token) > 1 and token[1] == "=":
                    op, ver = ">=", token[2:]
                else:
                    op, ver = ">", token[1:]
            elif token[0] == "<":
                if len(token) > 1 and token[1] == "=":
                    op, ver = "<=", token[2:]
                else:
                    op, ver = "<", token[1:]
            elif token[0] == "=":
                op, ver = "=", token[1:]
            elif token[0] == "^":
                op, ver = "^", token[1:]
            else:
                op, ver = "~", token[1:]
        else:
            op, ver = "=", token

        if not ver:
            raise ValueError("invalid comparator")

        return op, parse_version(ver)

    def parse_range(r):
        if not isinstance(r, str):
            raise ValueError("invalid range")

        sets = r.split("||")
        parsed_sets = []

        for set_str in sets:
            set_str = set_str.strip()
            if not set_str:
                raise ValueError("invalid range")

            comparators = set_str.split()
            if not comparators:
                raise ValueError("invalid range")

            parsed_comparators = []
            for comp in comparators:
                parsed_comparators.append(parse_comparator(comp))

            parsed_sets.append(parsed_comparators)

        return parsed_sets

    def caret_upper(v):
        major, minor, patch, _ = v
        if major > 0:
            return (major + 1, 0, 0, None)
        if minor > 0:
            return (0, minor + 1, 0, None)
        return (0, 0, patch + 1, None)

    def tilde_upper(v):
        major, minor, patch, _ = v
        return (major, minor + 1, 0, None)

    def comparator_satisfied(op, named, version):
        cmp_named = compare_versions(version, named)

        if op == "=":
            return cmp_named == 0
        if op == ">":
            return cmp_named > 0
        if op == ">=":
            return cmp_named >= 0
        if op == "<":
            return cmp_named < 0
        if op == "<=":
            return cmp_named <= 0
        if op == "^":
            return cmp_named >= 0 and compare_versions(version, caret_upper(named)) < 0
        if op == "~":
            return cmp_named >= 0 and compare_versions(version, tilde_upper(named)) < 0

        raise ValueError("invalid comparator")

    def prerelease_rule_ok(version, comparators):
        if version[3] is None:
            return True

        for _, named in comparators:
            if (
                named[3] is not None
                and version[0] == named[0]
                and version[1] == named[1]
                and version[2] == named[2]
            ):
                return True

        return False

    v = parse_version(version)
    parsed_range = parse_range(rng)

    for comparators in parsed_range:
        if all(comparator_satisfied(op, named, v) for op, named in comparators):
            if prerelease_rule_ok(v, comparators):
                return True

    return False
