        kind = op.get("op")
        path = op.get("path")

        if kind not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError

        if kind in {"add", "replace", "test"} and "value" not in op:
            raise PatchError
        if kind in {"move", "copy"} and "from" not in op:
            raise PatchError

        path_tokens = parse_pointer(path)

        if kind == "add":
            value = copy.deepcopy(op["value"])
            result = set_value(result, path_tokens, value)

        elif kind == "remove":
            result = remove_value(result, path_tokens)

        elif kind == "replace":
            if not path_tokens:
                result = copy.deepcopy(op["value"])
            else:
                get_value(result, path_tokens)
                result = set_value(result, path_tokens, copy.deepcopy(op["value"]))

        elif kind == "test":
            target = get_value(result, path_tokens)
            if not json_equal(target, op["value"]):
                raise PatchError

        elif kind == "move":
            from_tokens = parse_pointer(op["from"])
            result = move_value(result, from_tokens, path_tokens)

        elif kind == "copy":
            from_tokens = parse_pointer(op["from"])
            value = copy.deepcopy(get_value(result, from_tokens))
            result = set_value(result, path_tokens, value)

    return result
