def glob_match(pattern, path):
    """Return True if the "/"-separated relative `path` matches `pattern` (case-sensitive, whole path).

    Pattern syntax:
    - `?` matches exactly one character other than "/".
    - `*` matches zero or more characters other than "/".
    - `[...]` matches one character other than "/" that is in the set; `[!...]` one that is NOT in the set.
      The set holds literal characters and ranges `a-z`. A `]` right after `[` or `[!` is a literal member, and a
      `-` first or last in the set is literal. Backslash has no special meaning inside a set.
      An unterminated `[` raises ValueError.
    - `\\x` (backslash then any character) matches x literally. A trailing lone backslash raises ValueError.
    - A pattern segment (text between unescaped "/" outside sets) that is exactly `**` matches zero or more whole
      path segments. Elsewhere `**` is just two `*`.
    - Any other character matches itself.
    Matching must stay fast for patterns with many `*` or `**` (no exponential backtracking).
    """
    def parse_pattern(pattern):
        segments = []
        current = []
        i = 0
        n = len(pattern)

        while i < n:
            ch = pattern[i]

            if ch == "\\":
                if i + 1 >= n:
                    raise ValueError("trailing lone backslash")
                current.append(("literal", pattern[i + 1]))
                i += 2
                continue

            if ch == "/":
                segments.append(current)
                current = []
                i += 1
                continue

            if ch == "[":
                token, i = parse_set(pattern, i)
                current.append(token)
                continue

            if ch == "*":
                current.append(("star",))
                i += 1
                continue

            if ch == "?":
                current.append(("question",))
                i += 1
                continue

            current.append(("literal", ch))
            i += 1

        segments.append(current)
        return segments

    def parse_set(pattern, start):
        i = start + 1
        n = len(pattern)
        negated = False

        if i < n and pattern[i] == "!":
            negated = True
            i += 1

        members = []

        if i < n and pattern[i] == "]":
            members.append(("char", "]"))
            i += 1

        while i < n:
            if pattern[i] == "]":
                return (("negated_set" if negated else "set", members), i + 1)

            c = pattern[i]
            i += 1

            if i + 1 < n and pattern[i] == "-" and pattern[i + 1] != "]":
                low = c
                high = pattern[i + 1]
                i += 2
                if low <= high:
                    members.append(("range", low, high))
                else:
                    members.append(("char", low))
                    members.append(("char", "-"))
                    members.append(("char", high))
            else:
                members.append(("char", c))

        raise ValueError("unterminated [")

    def match_segment(segment, tokens):
        m = len(tokens)
        s = len(segment)

        dp = [[False] * (s + 1) for _ in range(m + 1)]
        dp[0][0] = True

        for pi in range(1, m + 1):
            token = tokens[pi - 1]

            if token[0] == "star":
                dp[pi][0] = dp[pi - 1][0]
                for si in range(1, s + 1):
                    dp[pi][si] = dp[pi - 1][si] or dp[pi][si - 1]
            else:
                for si in range(1, s + 1):
                    ch = segment[si - 1]

                    if token[0] == "literal":
                        if ch == token[1]:
                            dp[pi][si] = dp[pi - 1][si - 1]
                    elif token[0] == "question":
                        if ch != "/":
                            dp[pi][si] = dp[pi - 1][si - 1]
                    elif token[0] == "set":
                        if ch != "/" and set_match(token[1], ch):
                            dp[pi][si] = dp[pi - 1][si - 1]
                    elif token[0] == "negated_set":
                        if ch != "/" and not set_match(token[1], ch):
                            dp[pi][si] = dp[pi - 1][si - 1]

        return dp[m][s]

    def set_match(members, ch):
        for member in members:
            if member[0] == "char":
                if ch == member[1]:
                    return True
            else:
                if member[1] <= ch <= member[2]:
                    return True
        return False

    def is_double_star_segment(tokens):
        return len(tokens) == 2 and tokens[0] == ("star",) and tokens[1] == ("star",)

    pattern_segments = parse_pattern(pattern)
    path_segments = path.split("/")

    p_len = len(pattern_segments)
    s_len = len(path_segments)

    dp = [[False] * (s_len + 1) for _ in range(p_len + 1)]
    dp[0][0] = True

    for pi in range(1, p_len + 1):
        tokens = pattern_segments[pi - 1]

        if is_double_star_segment(tokens):
            dp[pi][0] = dp[pi - 1][0]
            for si in range(1, s_len + 1):
                dp[pi][si] = dp[pi - 1][si] or dp[pi][si - 1]
        else:
            for si in range(1, s_len + 1):
                if match_segment(path_segments[si - 1], tokens):
                    dp[pi][si] = dp[pi - 1][si - 1]

    return dp[p_len][s_len]
